arguments.content:
/* ===== RESET & BASE ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --red: #C41E3A;
  --red-dark: #A3182F;
  --red-light: #E8425A;
  --navy: #1B3A5C;
  --navy-dark: #122840;
  --navy-light: #2A5580;
  --white: #FFFFFF;
  --gray-50: #FAFAF9;
  --gray-100: #F5F3F0;
  --gray-200: #E8E4E0;
  --gray-300: #D1CCC6;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.18);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== UTILITY BAR ===== */
.utility-bar {
  background: var(--navy-dark);
  color: rgba(255,255,255,0.85);
  font-size: 0.8125rem;
  padding: 6px 0;
}

.utility-bar .container {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 20px;
}

.utility-bar a {
  color: rgba(255,255,255,0.85);
  transition: color var(--transition);
}

.utility-bar a:hover {
  color: var(--white);
}

.utility-bar .divider {
  width: 1px;
  height: 14px;
  background: rgba(255,255,255,0.25);
}

/* ===== HEADER ===== */
.header {
  background: var(--white);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

.header-main {
  padding: 0;
}

.header-main .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.25rem;
  color: var(--navy);
  flex-shrink: 0;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: var(--red);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.25rem;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 28px;
}

.nav-desktop a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: color var(--transition);
  white-space: nowrap;
}

.nav-desktop a:hover {
  color: var(--red);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(196,30,58,0.35);
}

.btn-secondary {
  background: var(--white);
  color: var(--navy);
  border: 2px solid var(--navy);
}

.btn-secondary:hover {
  background: var(--navy);
  color: var(--white);
  transform: translateY(-1px);
}

.btn-outline-white {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn-outline-white:hover {
  background: var(--white);
  color: var(--navy);
  transform: translateY(-1px);
}

.btn-nav {
  padding: 10px 22px;
  font-size: 0.875rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2.5px;
  background: var(--gray-800);
  border-radius: 2px;
  transition: all var(--transition);
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* ===== MOBILE NAV ===== */
.nav-mobile {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 150;
  padding: 80px 32px 32px;
  transition: right 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: var(--shadow-xl);
  overflow-y: auto;
}

.nav-mobile.open {
  right: 0;
}

.nav-mobile a {
  display: block;
  padding: 14px 0;
  font-size: 1.0625rem;
  font-weight: 500;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-200);
  transition: color var(--transition);
}

.nav-mobile a:hover {
  color: var(--red);
}

.nav-mobile .btn-primary {
  margin-top: 20px;
  width: 100%;
  text-align: center;
}

.nav-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 140;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
}

.nav-overlay.visible {
  opacity: 1;
  visibility: visible;
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 600px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 40%, var(--navy-light) 100%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 80%, rgba(196,30,58,0.15) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 20%, rgba(255,255,255,0.05) 0%, transparent 50%);
}

.hero::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 700px;
  height: 700px;
  border-radius: 50%;
  background: rgba(196,30,58,0.08);
}

.hero .container {
  position: relative;
  z-index: 2;
  padding-top: 60px;
  padding-bottom: 60px;
}

.hero-content {
  max-width: 680px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50px;
  padding: 6px 16px;
  color: rgba(255,255,255,0.9);
  font-size: 0.8125rem;
  font-weight: 500;
  margin-bottom: 24px;
  backdrop-filter: blur(4px);
}

.hero-badge i {
  color: var(--red-light);
}

.hero h1 {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1.1;
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}

.hero h1 span {
  color: var(--red-light);
}

.hero p {
  font-size: clamp(1rem, 2vw, 1.1875rem);
  color: rgba(255,255,255,0.85);
  line-height: 1.7;
  margin-bottom: 36px;
  max-width: 580px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.hero-actions .btn-primary {
  padding: 16px 36px;
  font-size: 1.0625rem;
}

.hero-actions .btn-outline-white {
  padding: 16px 36px;
  font-size: 1.0625rem;
}

/* ===== SECTION COMMON ===== */
.section {
  padding: 80px 0;
}

.section-alt {
  background: var(--gray-50);
}

.section-dark {
  background: var(--navy);
  color: var(--white);
}

.section-header {
  text-align: center;
  margin-bottom: 56px;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--gray-900);
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.section-dark .section-title {
  color: var(--white);
}

.section-subtitle {
  font-size: 1.0625rem;
  color: var(--gray-500);
  margin-top: 12px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.section-dark .section-subtitle {
  color: rgba(255,255,255,0.7);
}

/* ===== MISSION ===== */
.mission {
  border-bottom: 1px solid var(--gray-200);
}

.mission-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.mission-label {
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  margin-bottom: 16px;
}

.mission h2 {
  font-size: clamp(1.375rem, 3vw, 1.75rem);
  font-weight: 700;
  color: var(--gray-900);
  line-height: 1.5;
  margin-bottom: 24px;
}

.mission p {
  font-size: 1.0625rem;
  color: var(--gray-600);
  line-height: 1.8;
}

.mission-divider {
  width: 60px;
  height: 3px;
  background: var(--red);
  margin: 24px auto;
  border-radius: 2px;
}

/* ===== IMPACT STATS ===== */
.impact {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 100%);
  position: relative;
  overflow: hidden;
}

.impact::before {
  content: '';
  position: absolute;
  bottom: -100px;
  left: -100px;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: rgba(196,30,58,0.08);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  position: relative;
  z-index: 1;
}

.stat-card {
  text-align: center;
  padding: 32px 16px;
}

.stat-icon {
  width: 56px;
  height: 56px;
  background: rgba(196,30,58,0.2);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  font-size: 1.5rem;
  color: var(--red-light);
}

.stat-number {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--white);
  line-height: 1;
  margin-bottom: 8px;
  font-variant-numeric: tabular-nums;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
  font-weight: 500;
}

/* ===== PROGRAMS ===== */
.programs-list {
  max-width: 800px;
  margin: 0 auto;
}

.accordion-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  margin-bottom: 12px;
  overflow: hidden;
  transition: box-shadow var(--transition);
}

.accordion-item:hover {
  box-shadow: var(--shadow-md);
}

.accordion-item.active {
  border-color: var(--red);
  box-shadow: 0 4px 16px rgba(196,30,58,0.1);
}

.accordion-header {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  padding: 20px 24px;
  text-align: left;
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--gray-800);
  background: var(--white);
  transition: all var(--transition);
}

.accordion-header:hover {
  color: var(--red);
}

.accordion-item.active .accordion-header {
  color: var(--red);
  background: rgba(196,30,58,0.03);
}

.accordion-icon {
  width: 40px;
  height: 40px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--red);
  flex-shrink: 0;
}

.accordion-item.active .accordion-icon {
  background: var(--red);
  color: var(--white);
}

.accordion-chevron {
  margin-left: auto;
  font-size: 1.25rem;
  transition: transform var(--transition);
  color: var(--gray-400);
  flex-shrink: 0;
}

.accordion-item.active .accordion-chevron {
  transform: rotate(180deg);
  color: var(--red);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-body-inner {
  padding: 0 24px 24px 80px;
  font-size: 1rem;
  color: var(--gray-600);
  line-height: 1.7;
}

/* ===== GET INVOLVED ===== */
.involved-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.involved-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.involved-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.involved-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, rgba(196,30,58,0.1), rgba(196,30,58,0.05));
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: var(--red);
  margin-bottom: 20px;
}

.involved-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 12px;
}

.involved-card p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.7;
  margin-bottom: 24px;
  flex-grow: 1;
}

.involved-card .btn {
  align-self: flex-start;
  padding: 10px 22px;
  font-size: 0.875rem;
}

/* ===== NEWS ===== */
.news-carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.news-carousel {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  gap: 24px;
}

.news-card {
  min-width: calc(33.333% - 16px);
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
  flex-shrink: 0;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.news-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.news-card-img i {
  font-size: 3rem;
  color: rgba(255,255,255,0.3);
}

.news-card-img .news-tag {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--red);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 50px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.news-card-body {
  padding: 24px;
}

.news-card-body h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 10px;
  line-height: 1.4;
}

.news-card-body p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 16px;
}

.news-card-body .read-more {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--red);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}

.news-card-body .read-more:hover {
  gap: 8px;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  margin-top: 40px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--gray-600);
  transition: all var(--transition);
}

.carousel-btn:hover:not(:disabled) {
  border-color: var(--red);
  color: var(--red);
  background: rgba(196,30,58,0.05);
}

.carousel-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  padding: 0;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--red);
  width: 28px;
  border-radius: 5px;
}

/* ===== DONATE CTA ===== */
.donate-cta {
  background: linear-gradient(135deg, var(--red-dark) 0%, var(--red) 50%, var(--red-light) 100%);
  position: relative;
  overflow: hidden;
}

.donate-cta::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);
}

.donate-cta-content {
  text-align: center;
  position: relative;
  z-index: 1;
  max-width: 650px;
  margin: 0 auto;
}

.donate-cta h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
}

.donate-cta p {
  font-size: 1.0625rem;
  color: rgba(255,255,255,0.9);
  line-height: 1.7;
  margin-bottom: 32px;
}

.donate-cta .btn {
  background: var(--white);
  color: var(--red);
  font-size: 1.0625rem;
  padding: 16px 40px;
}

.donate-cta .btn:hover {
  background: var(--gray-100);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
}

/* ===== FOOTER ===== */
.footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.75);
  padding: 64px 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-top: 16px;
  color: rgba(255,255,255,0.6);
}

.footer-social {
  display: flex;
  gap: 12px;
  margin-top: 20px;
}

.footer-social a {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition);
}

.footer-social a:hover {
  background: var(--red);
  color: var(--white);
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--white);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  padding: 5px 0;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding: 24px 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.45);
}

/* ===== DONATE MODAL ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  padding: 24px;
  backdrop-filter: blur(4px);
}

.modal-overlay.open {
  opacity: 1;
  visibility: visible;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow-y: auto;
