  flex-shrink: 0;
}

.news-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.news-card-img {
  height: 200px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.news-card-img i {
  font-size: 3rem;
  color: rgba(255,255,255,0.3);
}

.news-card-img .news-tag {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--red);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 50px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.news-card-body {
  padding: 24px;
}

.news-card-body h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--gray-900);
  margin-bottom: 10px;
  line-height: 1.4;
}

.news-card-body p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 16px;
}

.news-card-body .read-more {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--red);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}

.news-card-body .read-more:hover {
  gap: 8px;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  margin-top: 40px;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--gray-600);
  transition: all var(--transition);
}

.carousel-btn:hover:not(:disabled) {
  border-color: var(--red);
  color: var(--red);
  background: rgba(196,30,58,0.05);
}

.carousel-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  padding: 0;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--red);
  width: 28px;
  border-radius: 5px;
}

/* ===== DONATE CTA ===== */
.donate-cta {
  background: linear-gradient(135deg, var(--red-dark) 0%, var(--red) 50%, var(--red-light) 100%);
  position: relative;
  overflow: hidden;
}

.donate-cta::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);
}

.donate-cta-content {
  text-align: center;
  position: relative;
  z-index: 1;
  max-width: 650px;
  margin: 0 auto;
}

.donate-cta h2 {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
}

.donate-cta p {
  font-size: 1.0625rem;
  color: rgba(255,255,255,0.9);
  line-height: 1.7;
  margin-bottom: 32px;
}

.donate-cta .btn {
  background: var(--white);
  color: var(--red);
  font-size: 1.0625rem;
  padding: 16px 40px;
}

.donate-cta .btn:hover {
  background: var(--gray-100);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
}

/* ===== FOOTER ===== */
.footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.75);
  padding: 64px 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-top: 16px;
  color: rgba(255,255,255,0.6);
}

.footer-social {
  display: flex;
  gap: 12px;
  margin-top: 20px;
}

.footer-social a {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition);
}

.footer-social a:hover {
  background: var(--red);
  color: var(--white);
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--white);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  padding: 5px 0;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  padding: 24px 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.45);
}

/* ===== DONATE MODAL ===== */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  padding: 24px;
  backdrop-filter: blur(4px);
}

.modal-overlay.open {
  opacity: 1;
  visibility: visible;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow-y: auto;
  transform: translateY(20px) scale(0.97);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: var(--shadow-xl);
}

.modal-overlay.open .modal {
  transform: translateY(0) scale(1);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 28px 0;
}

.modal-header h2 {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
}

.modal-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--gray-500);
  transition: all var(--transition);
}

.modal-close:hover {
  background: var(--gray-100);
  color: var(--gray-800);
}

.modal-body {
  padding: 24px 28px 28px;
}

.modal-body > p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  margin-bottom: 24px;
  line-height: 1.6;
}

.amount-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.amount-option {
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 16px;
  text-align: center;
  transition: all var(--transition);
  cursor: pointer;
}

.amount-option:hover {
  border-color: var(--red);
}

.amount-option.selected {
  border-color: var(--red);
  background: rgba(196,30,58,0.05);
}

.amount-option .amount {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
  display: block;
}

.amount-option .impact {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-top: 4px;
  display: block;
  line-height: 1.4;
}

.custom-amount {
  margin-bottom: 24px;
}

.custom-amount label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
  margin-bottom: 8px;
}

.custom-amount-input {
  display: flex;
  align-items: center;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition);
}

.custom-amount-input:focus-within {
  border-color: var(--red);
}

.custom-amount-input span {
  padding: 12px 14px;
  background: var(--gray-100);
  font-weight: 600;
  color: var(--gray-600);
  font-size: 1.0625rem;
}

.custom-amount-input input {
  border: none;
  outline: none;
  padding: 12px;
  font-size: 1.0625rem;
  width: 100%;
  font-family: inherit;
}

.modal-efficiency {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--gray-50);
  padding: 12px 16px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  font-size: 0.8125rem;
  color: var(--gray-600);
}

.modal-efficiency i {
  color: #16a34a;
  font-size: 1.25rem;
}

.modal .btn-primary {
  width: 100%;
  padding: 16px;
  font-size: 1.0625rem;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .nav-desktop {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 24px;
  }

  .involved-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .news-card {
    min-width: calc(50% - 12px);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 32px;
  }

  .footer-brand {
    grid-column: span 2;
  }
}

@media (max-width: 768px) {
  .utility-bar {
    display: none;
  }

  .section {
    padding: 56px 0;
  }

  .hero {
    min-height: 500px;
  }

  .hero-actions .btn {
    width: 100%;
    justify-content: center;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .stat-card {
    padding: 24px 12px;
  }

  .involved-grid {
    grid-template-columns: 1fr;
  }

  .news-card {
    min-width: 100%;
  }

  .accordion-body-inner {
    padding-left: 24px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-brand {
    grid-column: span 2;
  }

  .amount-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .hero h1 {
    font-size: 1.875rem;
  }

  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: span 1;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

/* ===== ANIMATIONS ===== */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(24px);
}

.animate-on-scroll.visible {
  animation: fadeInUp 0.6s ease forwards;
}

.animate-on-scroll:nth-child(2) { animation-delay: 0.1s; }
.animate-on-scroll:nth-child(3) { animation-delay: 0.2s; }
.animate-on-scroll:nth-child(4) { animation-delay: 0.3s; }

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--gray-100);
}

::-webkit-scrollbar-thumb {
  background: var(--gray-400);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--gray-500);
}
