  background: rgba(0,0,0,0.6);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  padding: 24px;
  backdrop-filter: blur(4px);
}

.modal-overlay.open {
  opacity: 1;
  visibility: visible;
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow-y: auto;
  transform: translateY(20px) scale(0.97);
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: var(--shadow-xl);
}

.modal-overlay.open .modal {
  transform: translateY(0) scale(1);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 28px 0;
}

.modal-header h2 {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
}

.modal-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--gray-500);
  transition: all var(--transition);
}

.modal-close:hover {
  background: var(--gray-100);
  color: var(--gray-800);
}

.modal-body {
  padding: 24px 28px 28px;
}

.modal-body > p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  margin-bottom: 24px;
  line-height: 1.6;
}

.amount-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.amount-option {
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 16px;
  text-align: center;
  transition: all var(--transition);
  cursor: pointer;
}

.amount-option:hover {
  border-color: var(--red);
}

.amount-option.selected {
  border-color: var(--red);
  background: rgba(196,30,58,0.05);
}

.amount-option .amount {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
  display: block;
}

.amount-option .impact {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-top: 4px;
  display: block;
  line-height: 1.4;
}

.custom-amount {
  margin-bottom: 24px;
}

.custom-amount label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
  margin-bottom: 8px;
}

.custom-amount-input {
  display: flex;
  align-items: center;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition);
}

.custom-amount-input:focus-within {
  border-color: var(--red);
}

.custom-amount-input span {
  padding: 12px 14px;
  background: var(--gray-100);
  font-weight: 600;
  color: var(--gray-600);
  font-size: 1.0625rem;
}

.custom-amount-input input {
  border: none;
  outline: none;
  padding: 12px;
  font-size: 1.0625rem;
  width: 100%;
  font-family: inherit;
}

.modal-efficiency {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--gray-50);
  padding: 12px 16px;
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  font-size: 0.8125rem;
  color: var(--gray-600);
}

.modal-efficiency i {
  color: #16a34a;
  font-size: 1.25rem;
}

.modal .btn-primary {
  width: 100%;
  padding: 16px;
  font-size: 1.0625rem;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .nav-desktop {
    display: none;
