  .hero-actions .btn {
    width: 100%;
    justify-content: center;
  }

  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .stat-card {
    padding: 24px 12px;
  }

  .involved-grid {
    grid-template-columns: 1fr;
  }

  .news-card {
    min-width: 100%;
  }

  .accordion-body-inner {
    padding-left: 24px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-brand {
    grid-column: span 2;
  }

  .amount-grid {
    grid-template-columns: 1fr 1fr;
  }
