    if (currentSlide > 0) {
      currentSlide--;
      updateCarousel();
    }
  });

  nextBtn.addEventListener('click', function () {
    if (currentSlide < getMaxSlide()) {
      currentSlide++;
      updateCarousel();
    }
  });

