    var scrollY = window.scrollY;
    if (scrollY > 50) {
      header.style.boxShadow = '0 2px 16px rgba(0,0,0,0.1)';
    } else {
      header.style.boxShadow = 'var(--shadow-sm)';
    }
    lastScroll = scrollY;
  });
});

